head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P7.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    $c.cm.PanelToGroupBox(panel_Top);

    // 데이터셋 초기화
    scwin.initDs();
    await scwin.search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Fz530_OnLoadError
 * @description dts_Fz530 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Fz530_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Fz530);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P7.dts_Fz530_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Fz531_OnLoadError
 * @description dts_Fz531 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Fz531_OnLoadError = async function() {
    try {
        // CloseWin(-1, grd_FZ530);
        await $c.win.alert(dts_Fz531);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P7.dts_Fz531_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Fz530_OnLoadCompleted
 * @description dts_Fz530 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Fz530_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_Fz530.errorMsg) {
            await $c.win.alert(dts_Fz530.errorMsg);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P7.dts_Fz530_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        // 닫기버튼 클릭
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P7.img_Close_onclick" });
    }
};

/**
 * @method
 * @name image_1_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.image_1_onclick = async function() {
    try {
        if (dts_Fz530.getRowPosition() < 1) {
            return;
        }
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P7.image_1_onclick" });
    }
};

/**
 * @method
 * @name trs_Delete_OnSuccess
 * @description Delete On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Delete_OnSuccess = async function() {
    try {
        // alert( getMessageParam("MSG-A001", "삭제") );
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        // 재조회
        await scwin.search();
        opener.fn_Reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P7.trs_Delete_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Delete_OnFail
 * @description Delete On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Delete_OnFail = async function() {
    try {
        await $c.win.alert(trs_Delete.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P7.trs_Delete_OnFail" });
    }
};

/**
 * @method
 * @name dts_Fz531_OnLoadCompleted
 * @description dts_Fz531 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Fz531_OnLoadCompleted = function(rowcount) {
    try {
        scwin.setParam();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00600_P7.dts_Fz531_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_FZ530_OnClick
 * @description grd_FZ530 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_FZ530_OnClick = async function(row, colid) {
    try {
        // 디테일 FZ531 조회
        await scwin.searchDetail(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P7.grd_FZ530_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.clearDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_Fz530",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Fz530=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name searchDetail
 * @description 디테일 조회
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function(row) {
    const sbmOptions = {
        id : "sbm_dts_Fz531",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Fz531=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name delete
 * @description 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!confirm("삭제하시겠습니까?")) {
        return;
    }
    // dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "EMP_NO", dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "EMP_NO"));
    dts_Delete.setCellData(1, "TYP", dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "TYP"));
    dts_Delete.setCellData(1, "GUBUN", dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "GUBUN"));
    dts_Delete.setCellData(1, "SEQ_NO", dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "SEQ_NO"));
    trs_Delete.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Delete",
        action : "/ConditionSrchAction.do",
        ref : "dts_Delete",
        target : "trs_Delete=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {

};

/**
 * @method
 * @name clearDs
 * @description 데이터셋 clear.
 * @returns {void}
 * @hidden N
 */
scwin.clearDs = function() {
    dts_Fz530.removeAll();
    dts_Fz531.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    return true;
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const pCondition = dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "CONTENT");
    // 조회조건을 화면에 세팅.
    const aCond = pCondition.split("|");
    let aCondPair;
    for (let i = 0; i < aCond.length; i++) {
        aCondPair = $c.stf.trim(aCond[i]).split("=");
        if (aCondPair[0] === "cmb_IND_PTTN") {
            opener.cmb_IND_PTTN.setValue(aCondPair[1]);
        }
    }
    opener.fn_setCondTitle("조건명 : " + dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "COND_NM"));
    opener.fn_setCondNm(dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "COND_NM"));
    opener.fn_setCondCon(dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "COND_CON"));
    opener.fn_SetCondition(dts_Fz531, dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "CONTENT"));
};
